        candidateMultiplier: 3,
        sizeRatio: [0.12, 0.18],
        widthRatio: [0.72, 1.05],
        outwardRatio: [1, 1.35],
        radialOffsetRatio: 0.01,
        exposureThreshold: 0.08,
        colorJitter: 0.04,
        paletteLift: 0.03,
        cavityScale: 0.35,
        normalBlend: 0.25,
        alphaTest: 0.5,
        planesPerCluster: 3,
        shadowProxyScale: 0.97,
        ...shellOverrides,
